/* generado por prompts/herramientas/clave-tests.js; no editar a mano */
(window.CLAVE_TEST=window.CLAVE_TEST||{})[15]=[{"a":"Artículo 5. Escolarización inmediata en caso de violencia de género","q":[{"i":"15-ia-1017","p":"Ley Orgánica 1/2004, de 28 de diciembre, de Medidas de Protección Integral contra la Violencia de Género. Escolarización inmediata en caso de violencia de género. Las Administraciones competentes deberán prever la escolarización __________ de los hijos que se vean afectados por un cambio de residencia derivada de actos de violencia de género:","o":["inmediata","preferente","gratuita","prioritaria"],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">inmediata</mark></span>El <span class=\"ref-norma\">art. 5 de la LO 1/2004</span> se dispone: <span class=\"ref-concepto\">\"deberán prever la escolarización inmediata de los hijos que se vean afectados por un cambio de residencia derivada de actos de violencia de género\"</span>. La escolarización es inmediata. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"15-143","p":"Según el artículo 5 de la Ley Orgánica 1/2004, ¿qué deben prever las Administraciones competentes en caso de violencia de género?","o":["El acceso prioritario a la vivienda social.","El cambio inmediato de colegio de los menores sin necesidad de trámite judicial.","La escolarización inmediata de los hijos que se vean afectados por un cambio de residencia derivada de actos de violencia de género.","El reconocimiento del derecho a la movilidad geográfica de la víctima."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La escolarización inmediata de los hijos que se vean afectados por un cambio de residencia derivada de actos de violencia de género.</mark></span><span class=\"ref-norma\">Art. 5 · Ley Orgánica 1/2004, de 28 de diciembre, de Medidas de Protección Integral contra la Violencia de Género</span>. El Artículo 5 (Escolarización inmediata en caso de violencia de género) establece esta obligación para las Administraciones competentes."},{"i":"15-283","p":"Según el artículo 5 de la Ley Orgánica 1/2004, ¿qué deben prever las Administraciones competentes en caso de violencia de género?","o":["El acceso prioritario a la vivienda social.","El cambio inmediato de colegio de los menores sin necesidad de trámite judicial.","La escolarización inmediata de los hijos que se vean afectados por un cambio de residencia derivada de actos de violencia de género.","El reconocimiento del derecho a la movilidad geográfica de la víctima."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La escolarización inmediata de los hijos que se vean afectados por un cambio de residencia derivada de actos de violencia de género.</mark></span><span class=\"ref-norma\">Art. 5 · Ley Orgánica 1/2004, de 28 de diciembre, de Medidas de Protección Integral contra la Violencia de Género</span>. Así lo establece el artículo 5 de la LO 1/2004, bajo la rúbrica \"Escolarización inmediata en caso de violencia de género\"."}]},{"a":"Artículo 12. Titulares de la acción de cesación y rectificación","q":[{"i":"15-8","p":"Ley Orgánica 1/2004, de 28 de diciembre, de Medidas de Protección Integral contra la Violencia de Género. Titulares de la acción de cesación y rectificación. Estarán legitimados para ejercitar ante los Tribunales la acción de cesación o rectificación prevista en esta Ley por utilizar en forma vejatoria la imagen de la mujer:","o":["La Delegación Especial del Gobierno contra la Violencia sobre la Mujer.","El Instituto de la Mujer o órgano equivalente de cada Comunidad Autónoma.","El Ministerio Fiscal y las Asociaciones que tengan como objetivo único la defensa de los intereses de la mujer.","Todos son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todos son correctas</mark></span>El <span class=\"ref-norma\">art. 12 de la LO 1/2004</span> dispone: <span class=\"ref-concepto\">\"La Delegación Especial del Gobierno contra la Violencia sobre la Mujer , el Instituto de la Mujer u órgano equivalente de cada Comunidad Autónoma, el Ministerio Fiscal y las Asociaciones que tengan como objetivo único la defensa de los intereses de la mujer estarán legitimados\"</span>. Los cuatro son titulares de la acción."},{"i":"15-144","p":"Ley Orgánica 1/2004, de 28 de diciembre, de Medidas de Protección Integral contra la Violencia de Género. Titulares de la acción de cesación y rectificación. ¿Cuál de los siguientes NO es titular de la acción de cesación de publicidad ilícita que utilice la imagen de la mujer con carácter vejatorio o discriminatorio?","o":["La Delegación Especial del Gobierno contra la Violencia sobre la Mujer.","El Instituto de la Mujer.","El Ministerio Fiscal.","El Defensor del Pueblo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">El Defensor del Pueblo</mark></span>El <span class=\"ref-norma\">art. 12 de la LO 1/2004</span> dispone: <span class=\"ref-concepto\">\"La Delegación Especial del Gobierno contra la Violencia sobre la Mujer , el Instituto de la Mujer u órgano equivalente de cada Comunidad Autónoma, el Ministerio Fiscal y las Asociaciones que tengan como objetivo único la defensa de los intereses de la mujer estarán legitimados\"</span>. El Defensor del Pueblo no figura entre los titulares."},{"i":"15-ia-1024","p":"Ley Orgánica 1/2004, de 28 de diciembre, de Medidas de Protección Integral contra la Violencia de Género. Titulares de la acción de cesación y rectificación. Las Asociaciones que tengan como objetivo __________ la defensa de los intereses de la mujer estarán legitimadas para ejercitar ante los Tribunales la acción de cesación de publicidad ilícita por utilizar en forma vejatoria la imagen de la mujer:","o":["principal","único","prioritario","esencial"],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">único</mark></span>El <span class=\"ref-norma\">art. 12 de la LO 1/2004</span> se dispone: <span class=\"ref-concepto\">\"las Asociaciones que tengan como objetivo único la defensa de los intereses de la mujer estarán legitimados para ejercitar ante los Tribunales la acción de cesación de publicidad ilícita\"</span>. El objetivo ha de ser «único». <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 14 ✱","q":[{"i":"15-46","p":"Ley Orgánica 1/2004, de 28 de diciembre, de Medidas de Protección Integral contra la Violencia de Género. Los medios de comunicación ________ la protección y salvaguarda de la igualdad entre hombre y mujer, evitando toda discriminación entre ellos.","o":["Fomentarán.","Garantizarán.","Corregirán.","Ninguna es correcta."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Fomentarán.</mark></span><span class=\"ref-norma\">Art. 14 · Ley Orgánica 1/2004, de 28 de diciembre, de Medidas de Protección Integral contra la Violencia de Género</span>. El Artículo 14 de la LO 1/2004 establece que los medios de comunicación de titularidad pública o privada fomentarán la protección y salvaguarda de la igualdad."},{"i":"15-290","p":"Ley Orgánica 1/2004, de 28 de diciembre, de Medidas de Protección Integral contra la Violencia de Género. Medios de comunicación. La difusión de informaciones relativas a la violencia sobre la mujer garantizará la defensa de los derechos humanos, la libertad y dignidad de las mujeres víctimas y de sus hijos. En particular, se tendrá especial cuidado en:","o":["La identificación de las víctimas en los medios impresos.","La difusión de las sentencias condenatorias en los medios digitales.","El tratamiento de las declaraciones del presunto agresor.","El tratamiento gráfico de las informaciones."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">El tratamiento gráfico de las informaciones</mark></span>El <span class=\"ref-norma\">art. 14 de la LO 1/2004</span> dispone: <span class=\"ref-concepto\">\"En particular, se tendrá especial cuidado en el tratamiento gráfico de las informaciones\"</span>"},{"i":"15-ia-1027","p":"Ley Orgánica 1/2004, de 28 de diciembre, de Medidas de Protección Integral contra la Violencia de Género. Los medios de comunicación. La difusión de informaciones relativas a la violencia sobre la mujer garantizará, con la correspondiente objetividad informativa, la defensa de los derechos humanos, la libertad y dignidad de las mujeres víctimas de violencia y de sus hijos. En particular, se tendrá especial cuidado en:","o":["la identificación de las víctimas, sin perjuicio de lo previsto en la normativa vigente.","el relato de los hechos violentos.","el tratamiento gráfico de las informaciones.","la difusión de datos personales."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">el tratamiento gráfico de las informaciones</mark></span>El <span class=\"ref-norma\">art. 14 de la LO 1/2004</span> se dispone: <span class=\"ref-concepto\">\"En particular, se tendrá especial cuidado en el tratamiento gráfico de las informaciones\"</span>. La Ley exige especial cuidado en el tratamiento gráfico. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 27. Ayudas sociales ✱ R5","q":[{"i":"15-ia-1103","p":"Ley Orgánica 1/2004, de 28 de diciembre, de Medidas de Protección Integral contra la Violencia de Género. Ayudas sociales. Cuando las víctimas de violencia de género careciesen de rentas superiores, en cómputo mensual, al 75 por 100 del salario mínimo interprofesional, excluida la parte proporcional de dos pagas extraordinarias, recibirán una ayuda de:","o":["pago periódico durante seis meses.","pago trimestral.","pago único.","pago mensual hasta su inserción laboral."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">pago único</mark></span>El <span class=\"ref-norma\">art. 27.1 de la LO 1/2004</span> se dispone: <span class=\"ref-concepto\">\"recibirán una ayuda de pago único, siempre que se presuma que debido a su edad\"</span>. Es una ayuda de pago único. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"15-58","p":"Ley Orgánica 1/2004, de medidas de protección integral contra la violencia de género. Cuando las víctimas de violencia de género careciesen de rentas superiores, en cómputo mensual, al ________ interprofesional, excluida la parte proporcional de dos pagas extraordinarias, recibirán una ayuda de pago único, siempre que se presuma que debido a su edad, falta de preparación general o especializada y circunstancias sociales, la víctima tendrá especiales dificultades para obtener un empleo y por dicha circunstancia no participará en los programas de empleo establecidos para su inserción profesional.","o":["85 por 100 del salario mínimo interprofesional","95 por 100 del salario mínimo interprofesional","75 por 100 del salario mínimo interprofesional","Todas son incorrectas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">75 por 100 del salario mínimo interprofesional</mark></span><span class=\"ref-norma\">Art. 27 · Ley Orgánica 1/2004, de 28 de diciembre, de Medidas de Protección Integral contra la Violencia de Género</span>. El Artículo 27 de la LOVG establece que el límite de rentas de la víctima para acceder a la ayuda económica de pago único es el 75% del Salario Mínimo Interprofesional (SMI)."},{"i":"15-145","p":"Para el acceso a las ayudas previstas en el artículo 27 de la Ley Orgánica 1/2004, si la víctima tiene responsabilidades familiares, ¿qué porcentaje del Salario Mínimo Interprofesional (SMI) no debe superar la renta mensual de la unidad familiar, dividida por el número de miembros, para cumplir el requisito de carencia de rentas?","o":["El 60% del SMI.","El 75% del SMI.","El 100% del SMI.","El 120% del SMI."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El 75% del SMI.</mark></span>La normativa de desarrollo (RD 87/2005) establece que, en caso de responsabilidades familiares, la renta no debe superar el 75% del SMI por miembro para acceder a la ayuda."},{"i":"15-250","p":"Ley Orgánica 1/2004, de 28 de diciembre, de Medidas de Protección Integral contra la Violencia de Género. Cuando las víctimas de violencia de género careciesen de rentas superiores, en cómputo mensual, ______________, excluida la parte proporcional de dos pagas extraordinarias, recibirán una ayuda de pago único, siempre que se presuma que debido a su edad, falta de preparación general o especializada y circunstancias sociales, la víctima tendrá especiales dificultades para obtener un empleo y por dicha circunstancia no participará en los programas de empleo establecidos para su inserción profesional.","o":["Al 65 por 100 del salario mínimo interprofesional.","Al 64 por 100 del salario mínimo interprofesional.","Al 75 por 100 del salario mínimo interprofesional.","Al 70 por 100 del salario mínimo interprofesional."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Al 75 por 100 del salario mínimo interprofesional.</mark></span><span class=\"ref-norma\">Art. 27 · Ley Orgánica 1/2004, de 28 de diciembre, de Medidas de Protección Integral contra la Violencia de Género</span>. El artículo 27 de la LO 1/2004 establece que la ayuda de pago único será de una cuantía equivalente al setenta y cinco por ciento (75%) del importe mensual del salario mínimo interprofesional."},{"i":"15-284","p":"Para el acceso a las ayudas previstas en el artículo 27 de la Ley Orgánica 1/2004, si la víctima tiene responsabilidades familiares, ¿qué porcentaje del Salario Mínimo Interprofesional (SMI) no debe superar la renta mensual de la unidad familiar, dividida por el número de miembros, para cumplir el requisito de carencia de rentas?","o":["El 60% del SMI.","El 75% del SMI.","El 100% del SMI.","El 120% del SMI."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El 75% del SMI.</mark></span><span class=\"ref-norma\">Art. 27.1 · Ley Orgánica 1/2004, de 28 de diciembre, de Medidas de Protección Integral contra la Violencia de Género</span>. El artículo 27.1 de la LO 1/2004 exige que las víctimas carezcan de rentas superiores, en cómputo mensual, al 75 por 100 del salario mínimo interprofesional (excluida la parte proporcional de dos pagas extraordinarias)."},{"i":"15-ia-1104","p":"Ley Orgánica 1/2004, de 28 de diciembre, de Medidas de Protección Integral contra la Violencia de Género. Ayudas sociales. La ayuda social se concede siempre que se presuma que, debido a su edad, falta de preparación general o especializada y circunstancias sociales, la víctima tendrá especiales dificultades para obtener un empleo y por dicha circunstancia no participará en los:","o":["cursos de formación para el empleo organizados por las comunidades autónomas.","programas de empleo establecidos para su inserción profesional.","procesos selectivos del empleo público.","planes de empleo del Servicio Público de Empleo Estatal."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">programas de empleo establecidos para su inserción profesional</mark></span>El <span class=\"ref-norma\">art. 27.1 de la LO 1/2004</span> se dispone: <span class=\"ref-concepto\">\"no participará en los programas de empleo establecidos para su inserción profesional\"</span>. Se trata de los programas de empleo establecidos para su inserción profesional. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"15-ia-1106","p":"Ley Orgánica 1/2004, de 28 de diciembre, de Medidas de Protección Integral contra la Violencia de Género. Ayudas sociales. Las ayudas sociales para víctimas de violencia de género, financiadas con cargo a los Presupuestos Generales del Estado, serán concedidas por:","o":["el Servicio Público de Empleo Estatal.","las Delegaciones del Gobierno.","los Juzgados de Violencia sobre la Mujer, salvo que la autoridad judicial disponga otra cosa.","las Administraciones competentes en materia de servicios sociales."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">las Administraciones competentes en materia de servicios sociales</mark></span>El <span class=\"ref-norma\">art. 27.3 de la LO 1/2004</span> se dispone: <span class=\"ref-concepto\">\"serán concedidas por las Administraciones competentes en materia de servicios sociales\"</span>. Las concede la Administración competente en servicios sociales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"15-ia-1107","p":"Ley Orgánica 1/2004, de 28 de diciembre, de Medidas de Protección Integral contra la Violencia de Género. Ayudas sociales. En la tramitación del procedimiento de concesión de la ayuda social deberá incorporarse informe del Servicio Público de Empleo referido a la previsibilidad de que la aplicación del programa de empleo no incida de forma sustancial en:","o":["la reducción de la tasa de desempleo, previo informe de la unidad policial competente.","el acceso a una vivienda protegida.","la mejora de la empleabilidad de la víctima.","la integración social de la víctima."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la mejora de la empleabilidad de la víctima</mark></span>El <span class=\"ref-norma\">art. 27.3 de la LO 1/2004</span> se dispone: <span class=\"ref-concepto\">\"la aplicación del programa de empleo no incida de forma sustancial en la mejora de la empleabilidad de la víctima\"</span>. El informe se refiere a la mejora de la empleabilidad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"15-ia-1108","p":"Ley Orgánica 1/2004, de 28 de diciembre, de Medidas de Protección Integral contra la Violencia de Género. Ayudas sociales. En el caso de que la víctima tenga responsabilidades familiares, el importe de la ayuda podrá alcanzar el de un período equivalente al de __________ de subsidio:","o":["12 meses, sin perjuicio de lo previsto en la normativa vigente.","18 meses","24 meses","15 meses"],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">18 meses</mark></span>El <span class=\"ref-norma\">art. 27.4 de la LO 1/2004</span> se dispone: <span class=\"ref-concepto\">\"su importe podrá alcanzar el de un período equivalente al de 18 meses de subsidio\"</span>. Con responsabilidades familiares puede alcanzar 18 meses (24 si hay minusvalía ≥ 33 %). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"15-265","p":"Ley Orgánica 1/2004, de medidas de protección integral contra la violencia de género. Cuando las víctimas de violencia de género careciesen de rentas superiores, en cómputo mensual, al 75 por 100 del salario mínimo interprofesional, excluida la parte proporcional de dos pagas extraordinarias, recibirán una ayuda de pago único, siempre que se presuma que debido a su edad, falta de preparación general o especializada y circunstancias sociales, la víctima tendrá especiales dificultades para obtener un empleo y por dicha circunstancia no participarán en los programas de empleo establecidos para su inserción profesional. En el caso de que la víctima tenga responsabilidades familiares, su importe podrá alcanzar el de un período equivalente al de:","o":["18 meses de subsidio, o de 24 meses si la víctima o alguno de los familiares que conviven con ella tiene reconocida oficialmente una minusvalía en grado igual o superior al 33 por 100, en los términos que establezcan las disposiciones de desarrollo de la presente Ley.","12 meses de subsidio, o de 24 meses si la víctima o alguno de los familiares que conviven con ella tiene reconocida oficialmente una minusvalía en grado igual o superior al 33 por 100, en los términos que establezcan las disposiciones de desarrollo de la presente Ley.","17 meses de subsidio, o de 18 meses si la víctima o alguno de los familiares que conviven con ella tiene reconocida oficialmente una minusvalía en grado igual o superior al 33 por 100, en los términos que establezcan las disposiciones de desarrollo de la presente Ley.","24 meses de subsidio, o de 30 meses si la víctima o alguno de los familiares que conviven con ella tiene reconocida oficialmente una minusvalía en grado igual o superior al 33 por 100, en los términos que establezcan las disposiciones de desarrollo de la presente Ley."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">18 meses de subsidio, o de 24 meses si la víctima o alguno de los familiares que conviven con ella tiene reconocida oficialmente una minusv…</mark></span><span class=\"ref-norma\">Art. 27.2 · Ley Orgánica 1/2004, de 28 de diciembre, de Medidas de Protección Integral contra la Violencia de Género</span>. El artículo 27.2 de la Ley Orgánica 1/2004 establece esta duración para la ayuda en caso de víctimas con responsabilidades familiares."},{"i":"15-ia-1109","p":"Ley Orgánica 1/2004, de 28 de diciembre, de Medidas de Protección Integral contra la Violencia de Género. Ayudas sociales. Estas ayudas serán compatibles con cualquiera de las previstas en la Ley 35/1995, de 11 de diciembre, de Ayudas y Asistencia a las Víctimas de Delitos Violentos y contra la Libertad Sexual, así como con:","o":["cualquier otra ayuda económica de carácter autonómico o local concedida por la situación de violencia de género.","las ayudas de la Seguridad Social por incapacidad temporal, pero no con las autonómicas, en los términos que se determinen reglamentariamente.","las prestaciones por desempleo, con excepción de las ayudas locales.","cualquier otra ayuda económica, salvo las de carácter local."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">cualquier otra ayuda económica de carácter autonómico o local concedida por la situación de violencia de género</mark></span>El <span class=\"ref-norma\">art. 27.5 de la LO 1/2004</span> se dispone: <span class=\"ref-concepto\">\"así como con cualquier otra ayuda económica de carácter autonómico o local concedida por la situación de violencia de género\"</span>. Son compatibles con cualquier otra ayuda autonómica o local. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 28. Acceso a la vivienda y residencias públicas para mayores R6","q":[{"i":"15-167","p":"Ley Orgánica 1/2004, de 28 de diciembre, de Medidas de Protección Integral contra la Violencia de Género. Acceso a la vivienda y residencias públicas para mayores. Las mujeres víctimas de violencia de género serán consideradas colectivos prioritarios:","o":["En el acceso a programas de empleo.","En el acceso a viviendas protegidas y residencias públicas para mayores.","En el acceso a subvenciones estatales.","Todas son incorrectas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">En el acceso a viviendas protegidas y residencias públicas para mayores.</mark></span><span class=\"ref-norma\">Art. 28 · Ley Orgánica 1/2004, de 28 de diciembre, de Medidas de Protección Integral contra la Violencia de Género</span>. El artículo 28 de la Ley Orgánica 1/2004, de 28 de diciembre, de Medidas de Protección Integral contra la Violencia de Género, establece que las mujeres víctimas de violencia de género serán consideradas colectivos prioritarios en el acceso a viviendas protegidas y residencias públicas para mayores, en los términos que determine la legislación aplicable."}]},{"a":"V.- COMUNICACIÓN DE DATOS ESTADÍSTICOS.","q":[{"i":"15-306","p":"Resolución de 28 de junio de 2005 (Protocolo de actuación de las FCS y coordinación con los órganos judiciales). Comunicación de datos estadísticos. Las Unidades Policiales, el CGPJ y la Fiscalía General del Estado se comprometen a realizar informes periódicos sobre datos relativos a la repercusión territorial de la violencia de género y doméstica, que se comunicarán al Ministerio de Justicia con objeto de:","o":["Elaborar el informe anual del Observatorio Estatal de la Violencia sobre la Mujer.","Determinar la dotación de medios de las Unidades policiales especializadas de cada territorio.","Planificar las campañas de sensibilización y prevención dirigidas a la sociedad.","Evaluar políticas de actuación para la toma de decisiones en materia de Planta Judicial."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Evaluar políticas de actuación para la toma de decisiones en materia de Planta Judicial</mark></span>El <span class=\"ref-norma\">V de la Resolución 28/06/2005</span> dispone: <span class=\"ref-concepto\">\"que se comunicarán al Ministerio de Justicia con objeto de evaluar políticas de actuación para la toma de decisiones en materia de Planta Judicial.\"</span>"}]},{"a":"8.- MANIFESTACIÓN DE LOS TESTIGOS ✱","q":[{"i":"15-311","p":"Resolución de 28 de junio de 2005 (Protocolo de actuación de las FCS y coordinación con los órganos judiciales). Contenidos mínimos del atestado. En la manifestación de los testigos se formularán, al menos, preguntas sobre si fue testigo ocular o de referencia, la descripción de los hechos por él conocidos y el:","o":["Parentesco con la víctima y con el presunto agresor.","Tiempo que lleva residiendo en la localidad de los hechos.","Conocimiento de otros supuestos similares ocurridos con anterioridad.","Intención de personarse como acusación particular en la causa, salvo que el órgano competente acuerde otra cosa de forma motivada."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Conocimiento de otros supuestos similares ocurridos con anterioridad</mark></span>El <span class=\"ref-norma\">Anexo I.8 de la Resolución 28/06/2005</span> dispone: <span class=\"ref-concepto\">\"• Conocimiento de otros supuestos similares ocurridos con anterioridad.\"</span>"}]},{"a":"2. ORGANIZACIÓN DEL SERVICIO Y COMETIDOS. ✱ R17 R18","q":[{"i":"15-ia-2232","p":"Norma Técnica de Funcionamiento NTF-2/2025 de la Guardia Civil, procedimiento de actuación de las Unidades de la Guardia Civil en materia de violencia de género. Anexo II: información a la víctima de violencia de género. El derecho a la asistencia jurídica gratuita asistirá también a los causahabientes, esto es, a las personas titulares de los derechos y bienes de la víctima, en caso de fallecimiento de la víctima, siempre que no fuera:","o":["su cónyuge.","el agresor.","un familiar directo.","su representante legal."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">el agresor</mark></span>En el <span class=\"ref-norma\">Anexo II, 2 de la NTF-2/2025 de la Guardia Civil</span> se dispone: <span class=\"ref-concepto\">\"en caso de fallecimiento de la víctima, siempre que no fuera el agresor\"</span>. Siempre que no fuera el agresor. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"15-ia-2019","p":"Norma Técnica de Funcionamiento NTF-2/2025 de la Guardia Civil, procedimiento de actuación de las Unidades de la Guardia Civil en materia de violencia de género. Finalidad y organización del servicio. La respuesta institucional debe basarse en la inmediatez de la actuación y en la atención a las circunstancias concretas y a la gravedad del hecho, para asegurar a las víctimas un tratamiento:","o":["adecuado, profesional y diligente.","personalizado, inmediato y confidencial.","adecuado, personalizado y específico.","específico, coordinado y eficaz."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">adecuado, personalizado y específico</mark></span>En el <span class=\"ref-norma\">punto 2 de la NTF-2/2025 de la Guardia Civil</span> se dispone: <span class=\"ref-concepto\">\"para asegurar a las víctimas un tratamiento adecuado, personalizado y específico\"</span>. El tratamiento es adecuado, personalizado y específico. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"15-319","p":"Norma Técnica de Funcionamiento NTF-2/2025 de la Guardia Civil. Puestos. El personal de los Puestos de la Guardia Civil conforma el primer nivel de respuesta dado que atienden:","o":["En primera instancia, la mayoría de los casos.","Exclusivamente los casos no graves, que derivan a los Equipos VIOGÉN.","Únicamente los casos con orden de protección en vigor.","Los casos graves, con el apoyo de los Puntos de Atención Especializada."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">En primera instancia, la mayoría de los casos</mark></span>El <span class=\"ref-norma\">2.1 de la NTF-2/2025</span> dispone: <span class=\"ref-concepto\">\"El personal de estas unidades conforma el primer nivel de respuesta dado que atienden, en primera instancia, la mayoría de los casos.\"</span>"},{"i":"15-76","p":"Norma Técnica de Funcionamiento NTF-2/2025 de la Guardia Civil, procedimiento de actuación de las Unidades en materia de violencia de género. Unidades de Seguridad Ciudadana (Puestos). Señale la opción INCORRECTA:","o":["Proporcionar la primera respuesta, adoptando las medidas necesarias para prestar auxilio a la víctima y garantizar su seguridad.","Hacerse cargo de las actuaciones en los casos no graves (recogida de la denuncia y Valoración Policial del Riesgo), siempre que no se haga cargo el Equipo VIOGEN.","Hacerse cargo de la protección de la víctima, de las actuaciones que procedan con el agresor, así como de vigilar la ejecución de las Medidas Judiciales, en su caso.","Hacerse cargo de las actuaciones en los casos graves."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Hacerse cargo de las actuaciones en los casos graves</mark></span>El <span class=\"ref-norma\">temario oficial</span> dispone: <span class=\"ref-concepto\">\"Hacerse cargo de las actuaciones en los casos no graves\"</span>. Los casos graves los asumen los PAEs, no los Puestos."},{"i":"15-ia-2021","p":"Norma Técnica de Funcionamiento NTF-2/2025 de la Guardia Civil, procedimiento de actuación de las Unidades de la Guardia Civil en materia de violencia de género. Cometidos de los Equipos VIOGEN y Jefaturas. Los Equipos VIOGEN llevarán a cabo los cometidos asignados en la Orden de Servicio 34/2021, con arreglo a las directrices de funcionamiento específicas de cada:","o":["Comandancia.","Compañía, en los términos que se determinen reglamentariamente.","Zona.","Puesto."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Comandancia</mark></span>En el <span class=\"ref-norma\">punto 2.2 de la NTF-2/2025 de la Guardia Civil</span> se dispone: <span class=\"ref-concepto\">\"con arreglo a las directrices de funcionamiento específicas de cada Comandancia\"</span>. Las directrices son específicas de cada Comandancia. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"15-ia-2022","p":"Norma Técnica de Funcionamiento NTF-2/2025 de la Guardia Civil, procedimiento de actuación de las Unidades de la Guardia Civil en materia de violencia de género. Cometidos de los Equipos VIOGEN y Jefaturas. En términos generales, los Equipos VIOGEN recogerán las denuncias y realizarán las correspondientes valoraciones policiales del riesgo:","o":["en los casos graves.","en los casos complejos.","cuando lo soliciten los Puestos.","siempre que sea posible."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">siempre que sea posible</mark></span>En el <span class=\"ref-norma\">punto 2.2 de la NTF-2/2025 de la Guardia Civil</span> se dispone: <span class=\"ref-concepto\">\"recogerán las denuncias y realizarán las correspondientes valoraciones policiales del riesgo siempre que sea posible\"</span>. Lo hacen siempre que sea posible. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"15-ia-2023","p":"Norma Técnica de Funcionamiento NTF-2/2025 de la Guardia Civil, procedimiento de actuación de las Unidades de la Guardia Civil en materia de violencia de género. Cometidos de los Equipos VIOGEN y Jefaturas. Los Equipos VIOGEN prestarán especial atención a la primera VPR, a los casos activados por Protocolo Cero, a los cambios en el nivel de riesgo, a las propuestas de inactivación, a las demoras activas y a:","o":["las incidencias de los dispositivos Cometa, salvo que la autoridad judicial disponga otra cosa.","las reactivaciones de los Casos Inactivos.","las reasignaciones (ya sean a otra Unidad o a otro Cuerpo Policial).","las comunicaciones a la Autoridad Judicial."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">las reasignaciones (ya sean a otra Unidad o a otro Cuerpo Policial)</mark></span>En el <span class=\"ref-norma\">punto 2.2 de la NTF-2/2025 de la Guardia Civil</span> se dispone: <span class=\"ref-concepto\">\"a las propuestas de inactivación, las demoras activas y las reasignaciones (ya sean a otra Unidad o a otro Cuerpo Policial)\"</span>. También vigilan las reasignaciones a otra Unidad o Cuerpo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"15-ia-2024","p":"Norma Técnica de Funcionamiento NTF-2/2025 de la Guardia Civil, procedimiento de actuación de las Unidades de la Guardia Civil en materia de violencia de género. Cometidos de los Equipos VIOGEN y Jefaturas. Los Equipos VIOGEN elevarán a los PAEs los casos que por sus características puedan ser considerados como:","o":["de especial relevancia.","graves y/o complejos.","de alta complejidad.","de agresores persistentes."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">graves y/o complejos</mark></span>En el <span class=\"ref-norma\">punto 2.2 de la NTF-2/2025 de la Guardia Civil</span> se dispone: <span class=\"ref-concepto\">\"Elevarán a los PAEs los casos que por sus características puedan ser considerados como graves y/o complejos\"</span>. Elevan los casos graves y/o complejos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"15-ia-2025","p":"Norma Técnica de Funcionamiento NTF-2/2025 de la Guardia Civil, procedimiento de actuación de las Unidades de la Guardia Civil en materia de violencia de género. Cometidos de los Equipos VIOGEN y Jefaturas. Los Equipos VIOGEN supervisarán el grado de cumplimiento de los compromisos adoptados por las Policías Locales en virtud de los procedimientos operativos de coordinación y colaboración vigentes en su demarcación e informarán de cualquier incumplimiento a:","o":["la Jefatura de la Comandancia.","la Jefatura de Zona.","la Delegación del Gobierno.","la Junta Local de Seguridad, previo informe de la unidad policial competente."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la Jefatura de la Comandancia</mark></span>En el <span class=\"ref-norma\">punto 2.2 de la NTF-2/2025 de la Guardia Civil</span> se dispone: <span class=\"ref-concepto\">\"informarán a la Jefatura de la Comandancia de cualquier incumplimiento por parte de éstas\"</span>. Informan a la Jefatura de la Comandancia. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"15-ia-2027","p":"Norma Técnica de Funcionamiento NTF-2/2025 de la Guardia Civil, procedimiento de actuación de las Unidades de la Guardia Civil en materia de violencia de género. Cometidos de los Equipos VIOGEN y Jefaturas. Los Equipos VIOGEN participarán en la difusión de la cultura de rechazo y sensibilización frente a la violencia de género en colaboración con las administraciones públicas, privadas y/o sociedad civil de ámbito:","o":["provincial.","autonómico.","local.","nacional."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">local</mark></span>En el <span class=\"ref-norma\">punto 2.2 de la NTF-2/2025 de la Guardia Civil</span> se dispone: <span class=\"ref-concepto\">\"en colaboración con las administraciones públicas, privadas y/o sociedad civil de ámbito local\"</span>. El ámbito es local. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"15-ia-2028","p":"Norma Técnica de Funcionamiento NTF-2/2025 de la Guardia Civil, procedimiento de actuación de las Unidades de la Guardia Civil en materia de violencia de género. Cometidos de los Equipos VIOGEN y Jefaturas. Las Jefaturas de Compañías establecerán y coordinarán las funciones de los Equipos VIOGEN que integran la Compañía, así como:","o":["la formación del personal de los mismos.","la dotación de recursos a los mismos.","la supervisión de sus actuaciones.","la comunicación con la Autoridad Judicial."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la dotación de recursos a los mismos</mark></span>En el <span class=\"ref-norma\">punto 2.3 de la NTF-2/2025 de la Guardia Civil</span> se dispone: <span class=\"ref-concepto\">\"Establecer y coordinar las funciones de los Equipos VIOGEN que integran la Compañía, así como la dotación de recursos a los mismos\"</span>. Les corresponde también la dotación de recursos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"15-ia-2034","p":"Norma Técnica de Funcionamiento NTF-2/2025 de la Guardia Civil, procedimiento de actuación de las Unidades de la Guardia Civil en materia de violencia de género. Puntos de Atención Especializada (PAEs). Las supervisiones realizadas por los PAEs se harán constar en el hecho creado al efecto en SIGO («Supervisión de caso de violencia de género H091896») indicando:","o":["qué unidades han realizado la supervisión, sin perjuicio de lo previsto en la normativa vigente.","qué incidencias se han detectado.","qué medidas se han adoptado.","qué actuaciones concretas han sido supervisadas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">qué actuaciones concretas han sido supervisadas</mark></span>En el <span class=\"ref-norma\">punto 2.6.1 de la NTF-2/2025 de la Guardia Civil</span> se dispone: <span class=\"ref-concepto\">\"indicando qué actuaciones concretas han sido supervisadas\"</span>. Se indican las actuaciones concretas supervisadas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"15-ia-2029","p":"Norma Técnica de Funcionamiento NTF-2/2025 de la Guardia Civil, procedimiento de actuación de las Unidades de la Guardia Civil en materia de violencia de género. Cometidos de los Equipos VIOGEN y Jefaturas. Las Jefaturas de Comandancia convocarán, al menos una vez al semestre, reuniones con representantes de los PAEs territoriales y de los Equipos VIOGÉN, con la finalidad de mejorar:","o":["la coordinación frente a la violencia de género en el ámbito territorial de la Comandancia.","la formación del personal de los Puestos.","la calidad de los datos grabados en el Sistema, en los términos que se determinen reglamentariamente.","la comunicación con las Policías Locales."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la coordinación frente a la violencia de género en el ámbito territorial de la Comandancia</mark></span>En el <span class=\"ref-norma\">punto 2.4 de la NTF-2/2025 de la Guardia Civil</span> se dispone: <span class=\"ref-concepto\">\"Convocar, al menos una vez al semestre, reuniones con representantes de los PAEs territoriales y de los Equipos VIOGÉN, con la finalidad de mejorar la coordinación frente a la violencia de género\"</span>. La finalidad es mejorar la coordinación frente a la violencia de género. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"15-68","p":"Norma Técnica de Funcionamiento NTF-2/2025 de la Guardia Civil, procedimiento de actuación de las Unidades en materia de violencia de género. Jefaturas de Comandancia. ¿Cuál de los siguientes cometidos NO desarrollarán las Jefaturas de Comandancia?","o":["Realizar un seguimiento de la casuística en esta materia en su territorio y velar por el cumplimiento de la normativa y protocolos de actuación.","Realizar un seguimiento de la casuística en las demarcaciones y supervisar la actuación de las Unidades subordinadas, impartiendo las instrucciones oportunas que garanticen la correcta aplicación de los protocolos establecidos.","Mantener las relaciones con las Subdelegaciones del Gobierno en esta materia, así como con los servicios centrales y asistencia a las víctimas, con objeto de coordinar la acción conjunta en materia de violencia de género.","Promover e implementar elementos de formación y actualización del personal de los Puestos y otro personal afectado para la aplicación de los protocolos establecidos en materia de violencia de género."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Realizar un seguimiento de la casuística en esta materia en su territorio y velar por el cumplimiento de la normativa y protocolos de actuación</mark></span>El <span class=\"ref-norma\">temario oficial</span> dispone: <span class=\"ref-concepto\">\"Realizar el seguimiento de la casuística en las demarcaciones y supervisar la actuación de las Unidades subordinadas, impartiendo las instrucciones oportunas que garanticen la correcta aplicación de los protocolos establecidos\"</span>. La opción A es cometido de las Jefaturas de Zona."},{"i":"15-ia-2030","p":"Norma Técnica de Funcionamiento NTF-2/2025 de la Guardia Civil, procedimiento de actuación de las Unidades de la Guardia Civil en materia de violencia de género. Cometidos de los Equipos VIOGEN y Jefaturas. Las Jefaturas de Zona mantendrán las relaciones con las Delegaciones del Gobierno y otros organismos involucrados en este ámbito de actuación, en su nivel de:","o":["competencia, salvo que la autoridad judicial disponga otra cosa.","territorio.","actuación.","responsabilidad."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">responsabilidad</mark></span>En el <span class=\"ref-norma\">punto 2.5 de la NTF-2/2025 de la Guardia Civil</span> se dispone: <span class=\"ref-concepto\">\"Mantener las relaciones con las Delegaciones del Gobierno y otros organismos involucrados en este ámbito de actuación, en su nivel de responsabilidad\"</span>. Lo hacen en su nivel de responsabilidad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"15-ia-2031","p":"Norma Técnica de Funcionamiento NTF-2/2025 de la Guardia Civil, procedimiento de actuación de las Unidades de la Guardia Civil en materia de violencia de género. Puntos de Atención Especializada (PAEs). Los Puntos de Atención Especializada (PAEs) están constituidos por los órganos de las Unidades Orgánicas de Policía Judicial: Equipos Territoriales de Policía Judicial (ETPJs) y Área de Personas de la Sección de Investigación que cuenten con personal especializado en:","o":["violencia de género (EVIOGEN).","atención a la víctima (OAV).","mujer-menor (EMUMEs).","investigación criminal (UIC)."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">mujer-menor (EMUMEs)</mark></span>En el <span class=\"ref-norma\">punto 2.6 de la NTF-2/2025 de la Guardia Civil</span> se dispone: <span class=\"ref-concepto\">\"Equipos Territoriales de Policía Judicial (ETPJs) y Área de Personas de la Sección de Investigación que cuenten con personal especializado en mujer-menor (EMUMEs)\"</span>. Cuentan con personal especializado en mujer-menor (EMUMEs). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"15-ia-2032","p":"Norma Técnica de Funcionamiento NTF-2/2025 de la Guardia Civil, procedimiento de actuación de las Unidades de la Guardia Civil en materia de violencia de género. Puntos de Atención Especializada (PAEs). Entre los cometidos del PAE comarcal (ETPJ) figura hacerse cargo de las actuaciones en los casos graves, que son aquéllos en los que se han producido:","o":["agresiones sexuales con penetración, previo informe de la unidad policial competente.","lesiones graves a la víctima, así como tentativas de homicidio.","privación de libertad de la víctima.","amenazas de muerte con arma."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">lesiones graves a la víctima, así como tentativas de homicidio</mark></span>En el <span class=\"ref-norma\">punto 2.6.1 de la NTF-2/2025 de la Guardia Civil</span> se dispone: <span class=\"ref-concepto\">\"Aquéllos en los que se han producido lesiones graves a la víctima, así como tentativas de homicidio\"</span>. Son los de lesiones graves o tentativas de homicidio. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"15-36","p":"Norma Técnica de Funcionamiento NTF-2/2025 de la Guardia Civil, procedimiento de actuación de las Unidades en materia de violencia de género. Puntos de Atención Especializada (PAEs), cometidos del PAE comarcal. Se consideran casos complejos los siguientes (señale la opción INCORRECTA):","o":["Aquéllos en los que la víctima y/o el autor sean componentes de las Fuerzas y Cuerpos de Seguridad o de Fuerzas Armadas.","Aquéllos en los que estén implicados los hijos menores convivientes, o las víctimas sean menores de edad, presenten discapacidad intelectual, trastorno psiquiátrico, o cualquier otra circunstancia que las haga especialmente vulnerables.","Aquéllos en los que el autor presente discapacidad intelectual, trastorno psiquiátrico o cualquier otra circunstancia que haga conveniente la intervención de estos especialistas.","Aquéllos en los que se han producido lesiones graves a la víctima, así como tentativas de homicidio."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Aquéllos en los que se han producido lesiones graves a la víctima, así como tentativas de homicidio</mark></span>El <span class=\"ref-norma\">temario oficial</span> dispone: <span class=\"ref-concepto\">\"Aquéllos en los que la víctima y/o el autor sean componentes de las Fuerzas y Cuerpos de Seguridad o de Fuerzas Armadas\"</span>. La D define los casos «graves», no los complejos."},{"i":"15-118","p":"Norma Técnica de Funcionamiento NTF-2/2025 de la Guardia Civil, procedimiento de actuación de las Unidades en materia de violencia de género. Cometidos del PAE provincial (Área de Personas-Sección de Investigación). Asumirá las funciones de PAE comarcal cuando:","o":["Se produzca un cese de las acciones graves (atestado o investigación).","Así se establezca por necesidades derivadas de la ausencia de personal.","Se presenten en los hechos dificultades o den lugar a repercusión social que dificulten su atención por los Equipos territoriales.","Todas son correctas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Así se establezca por necesidades derivadas de la ausencia de personal</mark></span>El <span class=\"ref-norma\">temario oficial</span> dispone: <span class=\"ref-concepto\">\"Asumir las funciones de PAE comarcal cuando así se establezca por necesidades derivadas de la ausencia de personal\"</span>."},{"i":"15-ia-2035","p":"Norma Técnica de Funcionamiento NTF-2/2025 de la Guardia Civil, procedimiento de actuación de las Unidades de la Guardia Civil en materia de violencia de género. Puntos de Atención Especializada (PAEs). Entre los cometidos del PAE provincial figura hacerse cargo de las actuaciones en los casos de:","o":["agresión sexual en el ámbito de la violencia de género.","lesiones graves a menores.","homicidio en el ámbito de la violencia de género.","quebrantamiento reiterado de medidas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">homicidio en el ámbito de la violencia de género</mark></span>En el <span class=\"ref-norma\">punto 2.6.2 de la NTF-2/2025 de la Guardia Civil</span> se dispone: <span class=\"ref-concepto\">\"Hacerse cargo de las actuaciones en los casos de homicidio en el ámbito de la violencia de género\"</span>. Se hace cargo de los casos de homicidio en el ámbito de la violencia de género. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"15-ia-2301","p":"Norma Técnica de Funcionamiento NTF-2/2025 de la Guardia Civil, procedimiento de actuación de las Unidades de la Guardia Civil en materia de violencia de género. Anexo IV: guía del instructor de las diligencias. Según la guía de intervención del instructor, si el caso es GRAVE, intervendrán los Emumes comarcales, quienes valorarán la conveniencia de que se hagan cargo los Emumes de la Sección en los casos:","o":["MUY GRAVES.","COMPLEJOS.","URGENTES.","RESISTENTES."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">MUY GRAVES</mark></span>En el <span class=\"ref-norma\">Anexo IV, 1 de la NTF-2/2025 de la Guardia Civil</span> se dispone: <span class=\"ref-concepto\">\"Si el caso es GRAVE, intervendrán los Emumes comarcales, quienes valorarán la conveniencia de que se hagan cargo los Emumes de la Sección en los casos MUY GRAVES\"</span>. En los casos muy graves. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"15-ia-2037","p":"Norma Técnica de Funcionamiento NTF-2/2025 de la Guardia Civil, procedimiento de actuación de las Unidades de la Guardia Civil en materia de violencia de género. Puntos de Atención Especializada (PAEs). El PAE central (JPJ-UTPJ) realizará el seguimiento del fenómeno a nivel central y garantizará una rápida respuesta en la recopilación de la información ante los casos en los que se produzca un desenlace que por su trascendencia o gravedad:","o":["lo requieran.","afecte a la seguridad nacional.","tenga repercusión mediática.","implique a miembros de las FFCCSS."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">lo requieran</mark></span>En el <span class=\"ref-norma\">punto 2.6.3 de la NTF-2/2025 de la Guardia Civil</span> se dispone: <span class=\"ref-concepto\">\"ante los casos en los que se produzca un desenlace que por su trascendencia o gravedad lo requieran\"</span>. Se actúa cuando la trascendencia o gravedad lo requieran. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"15-ia-2038","p":"Norma Técnica de Funcionamiento NTF-2/2025 de la Guardia Civil, procedimiento de actuación de las Unidades de la Guardia Civil en materia de violencia de género. Puntos de Atención Especializada (PAEs). El PAE central efectuará el análisis procedimental y técnico en los casos en los que se haya producido un desenlace no esperado y grave, con el objetivo de proponer:","o":["medidas disciplinarias.","modificaciones normativas.","actuaciones formativas.","medidas preventivas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">medidas preventivas</mark></span>En el <span class=\"ref-norma\">punto 2.6.3 de la NTF-2/2025 de la Guardia Civil</span> se dispone: <span class=\"ref-concepto\">\"con el objetivo de proponer medidas preventivas\"</span>. Propone medidas preventivas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"15-ia-2039","p":"Norma Técnica de Funcionamiento NTF-2/2025 de la Guardia Civil, procedimiento de actuación de las Unidades de la Guardia Civil en materia de violencia de género. Puntos de Atención Especializada (PAEs). El PAE central realizará las acciones formativas de actualización para el personal de:","o":["los Equipos VIOGEN.","las unidades de Seguridad Ciudadana.","los PAEs provinciales y comarcales.","las Jefaturas de Zona."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">los PAEs provinciales y comarcales</mark></span>En el <span class=\"ref-norma\">punto 2.6.3 de la NTF-2/2025 de la Guardia Civil</span> se dispone: <span class=\"ref-concepto\">\"Realizar las acciones formativas de actualización para el personal de los PAEs provinciales y comarcales\"</span>. Forma al personal de los PAEs provinciales y comarcales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]}];
